patch:
diff --git a/recreate/no-var-fix-reference-error.check.js b/recreate/no-var-fix-reference-error.check.js
new file mode 100644
index 0000000..acbfb5c
--- /dev/null
+++ b/recreate/no-var-fix-reference-error.check.js
@@ -0,0 +1,64 @@
+"use strict";
+
+/*
+ * Check: `no-var` autofix must not turn working code into code that throws
+ * a ReferenceError (var used before its declaration -> let in the same spot).
+ *
+ * Usage (from the repo root):
+ *   node recreate/no-var-fix-reference-error.check.js [path-to-eslint-package-or-lib/api]
+ * Default target is this checkout (./lib/api).
+ * Exit code: 0 = autofix output still runs, 1 = autofix output throws.
+ */
+
+const path = require("node:path");
+const vm = require("node:vm");
+
+const target = process.argv[2]
+	? path.resolve(process.argv[2])
+	: path.resolve(__dirname, "../lib/api");
+const { Linter } = require(target);
+
+const input = `export function a() {
+    console.log(o);
+    var o;
+    return o;
+}`;
+const config = [{ rules: { "no-var": ["error"] } }];
+
+/**
+ * Runs the snippet (export keyword stripped) and calls a().
+ * @param {string} code Source of the snippet.
+ * @returns {string|null} Error name and message, or null when it ran fine.
+ */
+function run(code) {
+	try {
+		const context = vm.createContext({ console: { log() {} } });
+		vm.runInContext(`${code.replace(/^export\s+/mu, "")}\na();`, context);
+		return null;
+	} catch (e) {
+		return `${e.name}: ${e.message}`;
+	}
+}
+
+const linter = new Linter();
+const version = Linter.version;
+const messages = linter.verify(input, config);
+const { output, fixed } = linter.verifyAndFix(input, config);
+
+console.log(`eslint ${version} (${target})`);
+console.log(`reported: ${messages.map(m => `${m.line}:${m.column} ${m.message} (${m.ruleId})`).join("; ")}`);
+console.log(`fix applied: ${fixed}`);
+console.log(`--- output after fix ---\n${output}\n------------------------`);
+
+const before = run(input);
+const after = run(output);
+
+if (before !== null) {
+	console.error(`SETUP ERROR: the original code already fails: ${before}`);
+	process.exit(2);
+}
+if (after !== null) {
+	console.error(`FAIL: original code runs fine, fixed code throws ${after}`);
+	process.exit(1);
+}
+console.log("PASS: fixed output runs without error");
